head.script:
	scwin.onpageload = function() {
        // $p.parent().$p.closePopup($p.parent().$p.getFrameId());
	};

	scwin.onpageunload = function() {
	};

	scwin.ibx_openPopup_onclick = function(e) {
		//requires("uiplugin.popup");
		var opts = {
			"id" : "popup_sub2",
			"type" : "wframePopup",
			"width" : "300px",
			"height" : "200px",
			"top" : 300,
			"left" : 300,
			"popupName" : "popup_sub2",
			"modal" : true,
			"useIFrame" : true,
			"title" : "popup_sub2",
			"disableCloseButton" : false,    // Close 버튼은 보이고 동작만 안하게 하는 설정
			"useControl" : true,             // controls 옵션이 동작하려면 true로 설정
			"controls" : { "minimize" : true, "maximize" : true, "close" : true },
			"processMsgFrame" : true,
			"windowDragMove" : true
		};
		$p.openPopup("popup_openPopup_modal_WESD-982_(WSQ-5324)_main.xml", opts);
	};
